#include "extension_form_state.h"
#include <iostream>
using namespace moon::extension;using namespace winrt::Windows::Data::Json;
void check(bool v,const char* why){if(!v)throw std::runtime_error(why);}
int main(){winrt::init_apartment();try{
 FormState form;const auto start=std::chrono::steady_clock::now();form.tick(start+std::chrono::seconds(16));check(!form.loadError().empty(),"15s stall");form.retry(start);check(form.loadError().empty()&&!form.loaded()&&form.generation()==1,"retry reset");
 auto nodes=JsonArray::Parse(LR"([{"id":"name","type":"input","value":""},{"id":"scale","type":"number","value":0},{"id":"event","type":"select","value":"idle"},{"id":"dependent","type":"text","visibleWhen":{"event":"tool"}},{"id":"save","type":"button","action":{"type":"save","values":"spoof","requestId":"spoof"}},{"id":"toggle","type":"toggle","action":{"type":"toggle"}},{"id":"slot","type":"slot","contextAction":{"type":"clear"},"children":[{"id":"file","type":"file","multiple":false,"action":{"type":"upload","animation":"SHOW"}}]}])");
 auto view=[&](const std::wstring& reply=L"",bool file=false){JsonObject v;v.Insert(L"nodes",nodes);if(!reply.empty()){JsonObject result;result.Insert(L"requestId",JsonValue::CreateStringValue(reply));if(file)result.Insert(L"file",JsonObject::Parse(LR"({"name":"cat.mspet","bytes":[1,2]})"));v.Insert(L"result",result);}return v;};
 check(!form.receive(view(),0)&&!form.loaded(),"stale load rejected");check(form.receive(view(),1)&&form.loaded()&&form.effectiveValue(L"scale").GetNumber()==0,"load and zero default");check(!form.shown(L"dependent"),"dependent hidden");check(form.edit(L"event",JsonValue::CreateStringValue(L"tool"))&&form.shown(L"dependent"),"draft dependency");check(form.edit(L"name",JsonValue::CreateStringValue(L"Test")),"draft edit");auto request=*form.click(L"save");check(form.busy()&&request.GetNamedString(L"requestId")==L"1"&&request.GetNamedObject(L"values").GetNamedString(L"name")==L"Test","action merge and drafts");check(!form.edit(L"name",JsonValue::CreateStringValue(L"busy"))&&!form.click(L"save"),"busy gates controls");
 int saved=0;auto save=[&](const FormState::File& file){++saved;check(file.name==L"cat.mspet"&&file.bytes==std::vector<std::uint8_t>{1,2},"export file payload");return false;};form.receive(view(L"unknown",true),1,save);check(!saved&&form.busy(),"push must not save/unlock");form.receive(view(L"1",true),1,save);check(saved==1&&!form.busy()&&form.drafts().Size()==0&&form.view().GetNamedString(L"status")==L"已取消导出","matching result export/reset");form.receive(view(L"1",true),1,save);check(saved==1,"result replay");
 request=*form.click(L"toggle",true);check(request.GetNamedBoolean(L"value")&&request.GetNamedString(L"requestId")==L"2","toggle extra");form.receive(view(L"2"),1);form.edit(L"name",JsonValue::CreateStringValue(L"old draft"));request=*form.context(L"slot");check(request.GetNamedObject(L"values").GetNamedString(L"name")==L"old draft"&&form.drafts().Size()==0,"context snapshot then draft reset");form.receive(view(request.GetNamedString(L"requestId").c_str()),1);
 check(!form.files(L"file",{})&&!form.busy(),"single upload count");request=*form.files(L"file",{{L"animation.gif",L"image/gif",{1,2}}});check(request.GetNamedString(L"animation")==L"SHOW"&&request.GetNamedArray(L"files").GetObjectAt(0).GetNamedArray(L"bytes").Size()==2,"named upload");const auto oldId=std::wstring(request.GetNamedString(L"requestId"));form.retry(start);check(!form.busy()&&!form.loaded()&&!form.receive(view(oldId),1),"retry generation isolation");form.receive(view(),2);request=*form.click(L"save");check(std::stoull(std::wstring(request.GetNamedString(L"requestId")))>std::stoull(oldId),"retry preserves sequence");
 auto invalid=view(request.GetNamedString(L"requestId").c_str(),true);invalid.GetNamedObject(L"result").GetNamedObject(L"file").Insert(L"name",JsonValue::CreateStringValue(L"../cat"));form.receive(invalid,2,save);check(saved==1&&!form.busy(),"invalid export rejected");request=*form.click(L"save");form.receive(view(request.GetNamedString(L"requestId").c_str(),true),2,[](const auto&)->bool{throw std::runtime_error("disk full");});check(!form.busy()&&form.view().GetNamedString(L"status")==L"disk full","save failure clears busy");
 JsonObject multi;multi.Insert(L"nodes",JsonArray::Parse(LR"([{"id":"uploads","type":"file"}])"));form.receive(multi,2);std::vector<FormState::File> batch(17);check(!form.files(L"uploads",batch)&&!form.busy(),"upload max16");batch.resize(16);check(bool(form.files(L"uploads",batch)),"upload sixteen allowed");form.retry();form.receive(view(),3);
 form.edit(L"name",JsonValue::CreateStringValue(std::wstring(80,L'x')));check(form.effectiveValue(L"name").GetString().size()==64,"input UTF16 max64");form.close();check(!form.click(L"save")&&!form.receive(view(),2)&&!form.active(),"closed form");
 std::cout<<"Form initialization/drafts/dependencies/actions/uploads/export replay/retry/failure/close passed\n";return 0;
 }catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}catch(const winrt::hresult_error& e){std::cerr<<winrt::to_string(e.message())<<'\n';return 1;}}
